pridem.mediaBlock:
/* Reduced motion (WCAG 2.3.3): travel goes to zero and durations collapse to
 * a short crossfade, so state changes stay readable without movement. The
 * View Transition and skeleton rules read the same tokens (global.css). */
@media (prefers-reduced-motion: reduce) {
  :root {
    --velo-dur-press: 0ms;
    --velo-dur-fast: 120ms;
    --velo-dur-base: 120ms;
    --velo-dur-page: 160ms;
    --velo-dur-page-exit: 120ms;
    --velo-dur-tab: 120ms;
    --velo-dur-tab-out: 60ms;
    --velo-dur-tab-in: 100ms;
    --velo-dur-resize: 0ms;
    --velo-dur-sheet: 160ms;
    --velo-dur-sheet-exit: 120ms;
    --velo-dur-calm: 200ms;
    --velo-dur-calm-long: 600ms;
    --velo-shift-page: 0px;
  }
}

